mapper.select:
SELECT r.id AS review_id, r.order_id, r.reviewer_id, u.nickname AS reviewer_nickname, u.avatar_url AS reviewer_avatar_url, r.rating, r.content, r.status, r.created_at FROM reviews r JOIN users u ON u.id = r.reviewer_id WHERE r.reviewee_id = #{revieweeId} AND r.status = 'VISIBLE'
AND r.rating = #{rating}
ORDER BY r.created_at DESC, r.id DESC
